card.statement:
Let $\la$ be an essentially typical highest weight. Then $L(\la)$ admits a basis $\xi_{\La}$ parameterized by all Gelfand-Tsetlin tableaux $\La$ which satisfy the following conditions:

- $\lambda_{m+n,i}=\lambda_i, \quad 1\leq i\leq m+n$;

- $\la_{k,i}-\la_{k-1,i}\equiv\theta_{k-1,i}\in\{0,1\}, 1\leq i\leq m;m+1\leq k\leq m+n$;

- $\la_{ki}-\la_{k,i+1}\in \mathrm{Z}_{\geq 0}, 1\leq i\leq m-1;m+1\leq k\leq m+n-1$;

- $\la_{k+1,i}-\la_{ki}\in \mathrm{Z}_{\geq 0}$ and $\la_{k,i}-\la_{k+1,i+1}\in \mathrm{Z}_{\geq 0},$ $1\leq i\leq k\leq m-1$ or $m+1\leq i\leq k\leq m+n-1$.

The action of the generators of $\gl_{m,n}$ is given by the formulas

\begin{equation}
h_{k}\xi_{\La}=\left(\sum_{i=1}^{k}\la_{kj}-\sum_{j=1}^{k-1}\la_{k-1,j}\right)\xi_{\La},\quad 1\leq k\leq m+n;
\\
\end{equation}

\begin{equation}
\noindent e_{k}\xi_{\La}=-\sum_{i=1}^{k}\frac{\Pi_{j=1}^{k+1}(l_{k+1,j}-l_{ki}) }
{\Pi_{j\neq i,j=1}^{k} (l_{kj}-l_{ki}) }\xi_{\La+\delta_{ki}},
\quad1\leq k\leq m-1;
\end{equation}

\begin{equation}
f_{k}\xi_{\La}=\sum_{i=1}^{k}\frac{\Pi_{j=1}^{k-1}(l_{k-1,j}-l_{ki})}
{\Pi_{j\neq i,j=1}^{k}(l_{kj}-l_{ki})}\xi_{\La-\delta_{ki}},
\quad  1\leq k\leq m-1;
\end{equation}

\begin{equation}
\begin{split}
e_{m}\xi_{\La}=\sum_{i=1}^{m}\theta_{mi}(-1)^{i-1}(-1)^{\theta_{m1}+\ldots+\theta_{m,i-1}}
\\
\times  \frac{\Pi_{1\leq j< i} (l_{mj}-l_{mi}-1)}
{\Pi_{i<j\leq m} (l_{mj}-l_{mi})
\Pi_{j\neq i,j=1}^{m}(l_{m+1,j}-l_{mi}-1)}
\xi_{\La+\delta_{mi}},
\\
\end{split}
\end{equation}

\begin{equation}
\begin{split}
f_{m} \xi_{\La}=\sum_{i=1}^{m}(1-\theta_{mi})(-1)^{i-1}(-1)^{\theta_{m1}+\ldots+\theta_{m,i-1}}
\\
\times  \frac{(l_{m,i}-l_{m+1,m+1})\Pi_{ i<j\leq m} (l_{mj}-l_{mi}+1)\Pi_{j=1}^{m-1}(l_{m-1,j}-l_{mi})}
{\Pi_{1\leq j< i} (l_{mj}-l_{mi})} \xi_{\La-\delta_{mi}},
\end{split}
\end{equation}

\begin{equation}
\begin{split}
e_k \xi_{\La}=\sum_{i=1}^{m}\theta_{ki}(-1)^{\theta_{k1}+\ldots+\theta_{k,i-1}
+\theta_{k-1,i+1}+\ldots+\theta_{k-1,m}}(1-\theta_{k-1,i})
\\
\times
\prod_{j\neq i,j =1}^{m}\left(\frac{l_{kj}-l_{ki}-1}{l_{k+1,j}-l_{ki}-1}\right)
\xi_{\La+\delta_{ki}}
\\
\\
-\sum_{i=m+1}^{k}
\Pi_{j=1}^{m}\left(\frac{(l_{kj}-l_{ki})(l_{kj}-l_{ki}+1)}{(l_{k+1,j}-l_{ki})(l_{k-1,j}-l_{ki}+1)} \right)
\\
\times
\frac{\Pi_{j=m+1}^{k+1}(l_{k+1,j}-l_{ki})}
{\Pi_{j\neq i,j=m+1}^{k} (l_{kj}-l_{ki})}\xi_{\La+\delta_{ki}} ,
\quad  m+1\leq k\leq m+n-1;
\\
\end{split}
\end{equation}

\begin{equation}
\begin{split}
f_{k}\xi_{\La}=
\sum_{i=1}^{m}\theta_{k-1,i}(-1)^{\theta_{k1}+\ldots+\theta_{k,i-1}+\theta_{k-1,i+1}+\ldots+\theta_{k-1,m}}(1-\theta_{ki})
\\
\times
\prod_{j\neq i=1}^{m}\left(\frac{l_{kj}-l_{ki}+1}{l_{k-1,j}-l_{ki}+1}\right)
\frac{\Pi_{j=m+1}^{k+1}(l_{k+1,j}-l_{ki})\Pi_{j=m+1}^{k-1}(l_{k-1,j}-l_{ki}+1)}
{\Pi_{j=m+1}^{k} (l_{kj}-l_{ki})(l_{kj}-l_{ki}+1)}\xi_{\La-\delta_{ki}}
\\
+ \sum_{i=m+1}^{k}
\frac{\prod_{j=m+1}^{k-1}(l_{k-1,j}-l_{ki})}{\prod_{j\neq i,j =m+1}^{k}(l_{k,j}-l_{ki})}
\xi_{\La-\delta_{ki}} \quad
m+1\leq k\leq m+n-1.
\end{split}
\end{equation}

The arrays $\La\pm \delta_{ki}$ are obtained from $\La$ by replacing $\la_{ki}$ by $\la_{ki}\pm1$. We assume that $\xi_{\La}=0$ if the array $\La$ does not satisfy the conditions of the theorem.
